  // CPU AI
  // -------------------------
  const evaluate = (b: number[], player: number) => {
    return b[ownStore(player)] - b[ownStore(1 - player)];
  };

  const minimax = (
    b: number[],
    depth: number,
    player: number,
    maximizing: boolean,
    rootPlayer: number
  ): { score: number; move?: number } => {
    if (depth === 0 || gameEnded(b)) return { score: evaluate(b, rootPlayer) };

    const legal: number[] = [];
    for (let i = 7; i <= 12; i++) if (b[i] > 0) legal.push(i);
    if (legal.length === 0) return { score: evaluate(b, rootPlayer) };

    if (maximizing) {
      let best = -Infinity;
      let bestMove = legal[0];
      for (const m of legal) {
        const res = applyMove(b, m, player);
        const next = minimax(
          res.board,
          depth - 1,
          res.extra ? player : 1 - player,
          res.extra ? true : false,
          rootPlayer
        );
        if (next.score > best) {
          best = next.score;
          bestMove = m;
        }
      }
      return { score: best, move: bestMove };
    } else {
      let best = Infinity;
      let bestMove = legal[0];
      for (const m of legal) {
        const res = applyMove(b, m, player);
        const next = minimax(
          res.board,
          depth - 1,
          res.extra ? player : 1 - player,
          res.extra ? false : true,
          rootPlayer
        );
        if (next.score < best) {
          best = next.score;
          bestMove = m;
        }
      }
      return { score: best, move: bestMove };
    }
  };

