    const legal: number[] = [];
    for (let i = 7; i <= 12; i++) if (board[i] > 0) legal.push(i);
    if (legal.length === 0) return null;

    if (difficulty === "easy") {
      return legal[Math.floor(Math.random() * legal.length)];
