          finishGame(board);
          return;
        }
        playMove(mv);
      }, 650);

      return () => clearTimeout(timeout);
    }
  }, [currentPlayer, opponent, gameOver, board, difficulty, isInteractive]);

  // -------------------------
  // END GAME
  // -------------------------
  const finishGame = (b: number[]) => {
    const final = finalize(b);
    setBoard(final);
    setGameOver(true);
    setIsInteractive(false);
    setShowVSOverlay(false);

    const p1 = final[6];
    const p2 = final[13];
