        Trash: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/></svg>,
        Undo: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 7v6h6"/><path d="M21 17a9 9 0 0 0-9-9 9 9 0 0 0-6 2.3L3 13"/></svg>,
        Wallet: () => <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 12V8H6a2 2 0 0 1-2-2c0-1.1.9-2 2-2h12v4"/><path d="M4 6v12c0 1.1.9 2 2 2h14v-4"/><path d="M18 12a2 2 0 0 0-2 2c0 1.1.9 2 2 2h4v-4h-4z"/></svg>,
        Spray: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 3h.01"/><path d="M7 5h.01"/><path d="M5 7h.01"/><path d="M3 7h.01"/><path d="M7 3h.01"/><path d="M5 3h.01"/><path d="M5 5h.01"/><path d="M11 7h.01"/><path d="M13 5h.01"/><path d="M15 3h.01"/><path d="M17 5h.01"/><path d="M19 3h.01"/><path d="M15 7h.01"/><path d="M15 13h4a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2Z"/><path d="M13 13v8"/><path d="M5 13h4a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2Z"/></svg>,
        Rainbow: () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M2 17a10 10 0 0 1 10-10"/><path d="M2 21a14 14 0 0 1 14-14"/><path d="M2 13a6 6 0 0 1 6-6"/><path d="M16 17a4 4 0 0 1 4-4"/><path d="M22 21a18 18 0 0 0-18-18"/></svg>,
        Settings: () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.1a2 2 0 0 1-1-1.72v-.51a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z"/><circle cx="12" cy="12" r="3"/></svg>
    };

    // --- App Component ---
    function App() {
        const canvasRef = useRef(null);
        const [isDrawing, setIsDrawing] = useState(false);
        const [color, setColor] = useState('#000000');

        // --- New State Variables ---
        const [brushSize, setBrushSize] = useState(15);
        const [opacity, setOpacity] = useState(100); // 0-100 scale
        const [sprayFlow, setSprayFlow] = useState(30); // 1-100 density

        const [tool, setTool] = useState('brush'); // 'brush', 'pencil', 'eraser'
        const [brushStyle, setBrushStyle] = useState('normal'); // 'normal', 'spray'
        // Note: 'pencil' is just a normal brush style conceptually, but we track it in `tool` for icon selection

        const [history, setHistory] = useState([]);

        const lastPos = useRef({ x: 0, y: 0 });
        const hueRef = useRef(0); 

        // Wallet State
        const [walletAddress, setWalletAddress] = useState(null);
        const [isMinting, setIsMinting] = useState(false);

        // Colors Palette
        const SCOTLAND_BLUE = '#005EB8';
        const colors = [
            'rainbow', // Rainbow Mode as a color option
            '#000000', // Black
            '#FFFFFF', // White
            '#FF0000', // Red
            '#FFA500', // Orange
            '#FFFF00', // Yellow
            '#008000', // Green
            '#0000FF', // Blue
            '#4B0082', // Indigo
            '#EE82EE', // Violet
        ];

        useEffect(() => {
            const canvas = canvasRef.current;
            const ctx = canvas.getContext('2d');

            const dpr = window.devicePixelRatio || 1;
            const rect = canvas.getBoundingClientRect();

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            ctx.scale(dpr, dpr);
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.fillStyle = 'white';
            ctx.fillRect(0, 0, rect.width, rect.height);

            saveState(); 
        }, []);

        const getCoordinates = (e) => {
            const canvas = canvasRef.current;
            const rect = canvas.getBoundingClientRect();

            let clientX, clientY;
            if (e.touches && e.touches.length > 0) {
                clientX = e.touches[0].clientX;
                clientY = e.touches[0].clientY;
            } else {
                clientX = e.clientX;
                clientY = e.clientY;
            }

            return {
                x: clientX - rect.left,
                y: clientY - rect.top
            };
        };

        const startDrawing = (e) => {
            e.preventDefault(); 
            setIsDrawing(true);
            const coords = getCoordinates(e);
            lastPos.current = coords;

            const ctx = canvasRef.current.getContext('2d');

            // Set Opacity
            ctx.globalAlpha = opacity / 100;

            if (brushStyle !== 'spray') {
                ctx.beginPath();
                ctx.moveTo(coords.x, coords.y);
                ctx.lineTo(coords.x, coords.y);

                if (color === 'rainbow') {
                     ctx.strokeStyle = `hsl(${hueRef.current}, 100%, 50%)`;
                } else {
                    ctx.strokeStyle = tool === 'eraser' ? '#FFFFFF' : color;
                }

                ctx.lineWidth = brushSize;
                ctx.stroke();
            } else {
                spray(ctx, coords.x, coords.y);
            }
        };

        const spray = (ctx, x, y) => {
            // Density depends on Flow Slider now
            const density = sprayFlow; 

            ctx.fillStyle = tool === 'eraser' ? '#FFFFFF' : color;

            for (let i = 0; i < density; i++) {
                const radius = brushSize / 2;
                const offsetX = (Math.random() - 0.5) * brushSize;
                const offsetY = (Math.random() - 0.5) * brushSize;

                if (offsetX*offsetX + offsetY*offsetY <= radius*radius) {
                    if (color === 'rainbow') { 
                        ctx.fillStyle = `hsl(${Math.random() * 360}, 100%, 50%)`;
                    }
                    ctx.fillRect(x + offsetX, y + offsetY, 1.5, 1.5); 
                }
            }
        };

        const draw = (e) => {
            if (!isDrawing) return;
            e.preventDefault();

            const { x, y } = getCoordinates(e);
            const ctx = canvasRef.current.getContext('2d');

            // Ensure Opacity is set during drag
            ctx.globalAlpha = opacity / 100;

            if (brushStyle === 'spray' && tool !== 'eraser') {
                spray(ctx, x, y);
            } else {
                ctx.beginPath();
                ctx.moveTo(lastPos.current.x, lastPos.current.y);
                ctx.lineTo(x, y);

                ctx.lineWidth = brushSize;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';

                if (tool === 'eraser') {
                    ctx.strokeStyle = '#FFFFFF';
                } else if (color === 'rainbow') {
                    hueRef.current = (hueRef.current + 2) % 360; 
                    ctx.strokeStyle = `hsl(${hueRef.current}, 100%, 50%)`;
                } else {
                    ctx.strokeStyle = color;
                }

                ctx.stroke();
            }

            lastPos.current = { x, y };
        };

        const stopDrawing = () => {
            if (isDrawing) {
                setIsDrawing(false);
                saveState();
            }
        };

        const saveState = () => {
            const canvas = canvasRef.current;
            if(history.length > 10) {
                const newHistory = [...history.slice(1), canvas.toDataURL()];
                setHistory(newHistory);
            } else {
                setHistory([...history, canvas.toDataURL()]);
            }
        };

        const undo = () => {
            if (history.length <= 1) return;

            const newHistory = [...history];
            newHistory.pop(); 
            const previousState = newHistory[newHistory.length - 1];
            setHistory(newHistory);

            const img = new Image();
            img.src = previousState;
            img.onload = () => {
                const canvas = canvasRef.current;
                const ctx = canvas.getContext('2d');

                // Important: Reset alpha to 1 for restoring state!
                ctx.globalAlpha = 1.0; 

                const rect = canvas.getBoundingClientRect();
                ctx.fillStyle = 'white';
                ctx.fillRect(0, 0, rect.width, rect.height);
                ctx.drawImage(img, 0, 0, rect.width, rect.height);

                // Reset back to user setting
                ctx.globalAlpha = opacity / 100;
            };
        };

        const clearCanvas = () => {
            const canvas = canvasRef.current;
            const ctx = canvas.getContext('2d');

            // Important: Reset alpha to 1 for clearing!
            ctx.globalAlpha = 1.0;

            const rect = canvas.getBoundingClientRect();
            ctx.fillStyle = 'white';
            ctx.fillRect(0, 0, rect.width, rect.height);
            saveState();

            // Reset back to user setting
            ctx.globalAlpha = opacity / 100;
        };

        const connectWallet = async () => {
            if (window.ethereum) {
                try {
                    const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
                    setWalletAddress(accounts[0]);
                } catch (error) {
                    alert("Connection failed or rejected");
                }
            } else {
                const mockAddr = "0x" + Math.random().toString(16).substr(2, 40);
                setWalletAddress(mockAddr);
            }
        };

        const handleMint = async () => {
            if (!walletAddress) {
                alert("Please connect your wallet first!");
                return;
            }
            setIsMinting(true);
            await new Promise(resolve => setTimeout(resolve, 2000));
            setIsMinting(false);
            confetti({
                particleCount: 200,
                spread: 100,
                origin: { y: 0.6 },
                colors: ['#FF0000', '#FFA500', '#FFFF00', '#008000', '#0000FF', '#4B0082', '#EE82EE']
            });
            alert("Minted Successfully!");
        };

        return (
            <div className="flex flex-col h-screen max-w-md mx-auto bg-white shadow-2xl relative overflow-hidden">

                {/* Header */}
                <div className="p-4 bg-white border-b border-gray-200 flex justify-between items-center z-10">
                    <div className="flex items-center gap-2">
                        <div className="w-8 h-8 rounded-lg flex items-center justify-center text-white font-bold bg-[#005EB8]">
                            S
                        </div>
                        <h1 className="font-bold text-xl tracking-tight text-gray-800">Scribble Mint</h1>
                    </div>
                    <button 
                        onClick={connectWallet}
                        className={`px-3 py-1.5 rounded-full text-sm font-medium flex items-center gap-2 transition-all ${walletAddress ? 'bg-green-100 text-green-700' : 'bg-[#005EB8] text-white shadow-lg shadow-[#005EB8]/30'}`}
                    >
                        <Icons.Wallet />
                        {walletAddress ? `${walletAddress.substring(0,4)}...${walletAddress.substring(38)}` : 'Connect'}
                    </button>
                </div>

                {/* Canvas Area */}
                <div className="flex-1 bg-gray-100 relative p-4 flex items-center justify-center overflow-hidden">
                    <div className="relative w-full h-full max-h-[600px] shadow-xl bg-white rounded-xl overflow-hidden canvas-container border border-gray-300">
                        <canvas 
                            ref={canvasRef}
                            className="w-full h-full touch-none cursor-crosshair"
                            onMouseDown={startDrawing}
                            onMouseMove={draw}
                            onMouseUp={stopDrawing}
                            onMouseLeave={stopDrawing}
                            onTouchStart={startDrawing}
                            onTouchMove={draw}
                            onTouchEnd={stopDrawing}
                        ></canvas>
                    </div>
                </div>

                {/* Tools Dock */}
                <div className="bg-white border-t border-gray-200 p-4 pb-6 z-20">

                    {/* Row 1: Controls (Size, Opacity, Flow) */}
                    <div className="grid grid-cols-[1fr_auto] gap-4 mb-4 items-start">
                        <div className="space-y-3">

                            {/* Size & Opacity Container */}
                            <div className="grid grid-cols-2 gap-3">
                                {/* Size Slider */}
                                <div>
                                    <div className="flex justify-between text-xs text-gray-500 font-bold uppercase mb-1">
                                        <span>Size</span>
                                        <span>{brushSize}px</span>
                                    </div>
                                    <input 
                                        type="range" min="2" max="50" 
                                        value={brushSize} 
                                        onChange={(e) => setBrushSize(e.target.value)}
                                        className="w-full"
                                    />
                                </div>

                                {/* Opacity Slider */}
                                <div>
                                    <div className="flex justify-between text-xs text-gray-500 font-bold uppercase mb-1">
                                        <span>Opacity</span>
                                        <span>{opacity}%</span>
                                    </div>
                                    <input 
                                        type="range" min="1" max="100" 
                                        value={opacity} 
                                        onChange={(e) => setOpacity(e.target.value)}
                                        className="w-full"
                                    />
                                </div>
                            </div>

                            {/* Flow Slider (Only for Spray) */}
                            {brushStyle === 'spray' && (
                                <div>
                                    <div className="flex justify-between text-xs text-gray-500 font-bold uppercase mb-1">
                                        <span>Spray Flow</span>
                                        <span>{sprayFlow}</span>
                                    </div>
                                    <input 
                                        type="range" min="5" max="150" 
                                        value={sprayFlow} 
                                        onChange={(e) => setSprayFlow(e.target.value)}
                                        className="w-full accent-orange-500"
                                    />
                                </div>
                            )}
                        </div>

                        {/* Undo/Trash Buttons */}
                        <div className="flex flex-col gap-2 pt-1">
                            <button onClick={undo} className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg border border-gray-200"><Icons.Undo /></button>
                            <button onClick={clearCanvas} className="p-2 text-red-500 hover:bg-red-50 rounded-lg border border-gray-200"><Icons.Trash /></button>
                        </div>
                    </div>

                    {/* Row 2: Tool Selection */}
                    <div className="flex items-center justify-between mb-4 px-1">
                         <div className="flex gap-4 w-full justify-center bg-gray-50 p-2 rounded-xl border border-gray-100">
                            <button 
                                onClick={() => { setTool('pencil'); setBrushStyle('normal'); }}
                                className={`p-2 rounded-lg transition-all ${tool === 'pencil' && brushStyle === 'normal' ? 'bg-white text-[#005EB8] shadow-md scale-110' : 'text-gray-400 hover:text-gray-600'}`}
                                title="Pencil"
                            ><Icons.Pencil /></button>

                            <button 
                                onClick={() => { setTool('brush'); setBrushStyle('normal'); }}
                                className={`p-2 rounded-lg transition-all ${tool === 'brush' && brushStyle === 'normal' ? 'bg-white text-[#005EB8] shadow-md scale-110' : 'text-gray-400 hover:text-gray-600'}`}
                                title="Brush"
                            ><Icons.Brush /></button>

                            <button 
                                onClick={() => { setTool('brush'); setBrushStyle('spray'); }}
                                className={`p-2 rounded-lg transition-all ${brushStyle === 'spray' ? 'bg-white text-orange-500 shadow-md scale-110' : 'text-gray-400 hover:text-gray-600'}`}
                                title="Spray Can"
                            ><Icons.Spray /></button>

                            <button 
                                onClick={() => setTool('eraser')}
                                className={`p-2 rounded-lg transition-all ${tool === 'eraser' ? 'bg-white text-gray-800 shadow-md scale-110' : 'text-gray-400 hover:text-gray-600'}`}
                                title="Eraser"
                            ><Icons.Eraser /></button>
                        </div>
                    </div>

                    {/* Row 3: Colors */}
                    <div className="flex items-center justify-between mb-4">
                        <div className="flex gap-2 overflow-x-auto hide-scrollbar py-1 w-full">
                            {colors.map((c) => (
                                <button 
                                    key={c}
                                    onClick={() => { setColor(c); if(tool === 'eraser') { setTool('brush'); } }}
                                    className={`flex-shrink-0 w-8 h-8 rounded-full border border-gray-200 transition-transform active:scale-90 ${color === c && tool !== 'eraser' ? 'ring-2 ring-offset-2 ring-[#005EB8] scale-105' : ''}`}
                                    style={{ background: c === 'rainbow' ? 'linear-gradient(135deg, #FF0000, #FF7F00, #FFFF00, #00FF00, #0000FF, #4B0082, #9400D3)' : c }}
                                    title={c === 'rainbow' ? "Rainbow Mode" : c}
                                >
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Row 4: Mint */}
                    <button 
                        onClick={handleMint}
                        disabled={isMinting}
                        className="w-full py-3.5 bg-[#005EB8] hover:opacity-90 active:opacity-100 text-white font-bold rounded-xl shadow-lg shadow-[#005EB8]/30 transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {isMinting ? (
                            <span className="flex items-center gap-2">Minting...</span>
                        ) : (
                            "MINT DOODLE"
                        )}
                    </button>
                </div>

            </div>
        );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<App />);
</script>

</body>
</html>

