<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Monster Chase Maze</title>
<style>
  body { font-family: monospace; text-align: center; background: #111; color: #fff; }
  pre { font-size: 32px; line-height: 1.2; display: inline-block; margin: 20px auto; }
  button { font-size: 20px; margin: 5px; padding: 10px; }
  #message { font-size: 24px; margin-top: 10px; }
</style>
</head>
<body>
<h1>Monster Chase Maze 🧍👹🟧</h1>
<div id="message"></div>
<pre id="grid"></pre>
<div>
  <button onclick="move('Up')">Up</button>
  <button onclick="move('Down')">Down</button>
  <button onclick="move('Left')">Left</button>
  <button onclick="move('Right')">Right</button>
  <button onclick="initGame()">Restart</button>
</div>
<script>
let rows, cols;
let maze = [];
let playerX, playerY;
let monsterX, monsterY;
let exitX, exitY;
let moves, timeLeft, gameOver;
let messageEl = document.getElementById('message');
let gridEl = document.getElementById('grid');
// INIT
function initGame() {
  rows = 10; cols = 10;
  maze = Array.from({length: rows}, ()=> Array(cols).fill(0));
  // carve guaranteed path
  let x = 0, y = 0;
  maze[y][x] = 1;
  while (x < cols-1 || y < rows-1) {
    if (Math.random() < 0.5 && x < cols-1) x++;
    else if (y < rows-1) y++;
    maze[y][x] = 1;
  }
  // extra random paths
  for (let i = 0; i < 40; i++) {
    let rx = Math.floor(Math.random()*cols);
    let ry = Math.floor(Math.random()*rows);
    maze[ry][rx] = 1;
  }
  // player start
  playerX = 0; 
  playerY = 0;
  // monster placement
  [monsterX, monsterY] = placeMonster();
  // exit placement (safe & reachable)
  while (true) {
    exitX = Math.floor(Math.random()*cols);
    exitY = Math.floor(Math.random()*rows);
    if (maze[exitY][exitX] !== 1) continue;
    if ((exitX === playerX && exitY === playerY) ||
        (exitX === monsterX && exitY === monsterY)) continue;
    let neighbors = [
      [exitX+1, exitY],
      [exitX-1, exitY],
      [exitX, exitY+1],
      [exitX, exitY-1]
    ];
    let hasOpenNeighbor = neighbors.some(([nx, ny]) =>
      nx>=0 && ny>=0 && nx<cols && ny<rows &&
      maze[ny][nx] === 1
    );
    if (!hasOpenNeighbor) continue;
    if (!isReachable(playerX, playerY, exitX, exitY)) continue;
    break;
  }
  moves = 0;
  timeLeft = 30;
  gameOver = false;
  messageEl.textContent = "Escape the maze!";
  render();
}
// place monster
function placeMonster() {
  let x = cols-1, y = rows-1;
  if (maze[y][x] === 1) return [x, y];
  for (let yy = rows-1; yy >= 0; yy--) {
    for (let xx = cols-1; xx >= 0; xx--) {
      if (maze[yy][xx] === 1) return [xx, yy];
    }
  }
  return [cols-1, rows-1];
}
// BFS
function isReachable(sx, sy, ex, ey) {
  let visited = Array.from({length: rows}, ()=> Array(cols).fill(false));
  let queue = [[sx, sy]];
  visited[sy][sx] = true;
  while (queue.length > 0) {
    let [x, y] = queue.shift();
    if (x === ex && y === ey) return true;
    for (let [nx, ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]]) {
      if (nx>=0 && ny>=0 && nx<cols && ny<rows &&
          maze[ny][nx] === 1 && !visited[ny][nx]) {
        visited[ny][nx] = true;
        queue.push([nx, ny]);
      }
    }
  }
  return false;
}
// movement
function move(dir) {
  if (gameOver) return;
  let nx = playerX, ny = playerY;
  if (dir === "Up") ny--;
  if (dir === "Down") ny++;
  if (dir === "Left") nx--;
